// the application aspect — invoked over targets, may be a separate process
protocol OpenFacet   { func open(_ target: LocalTarget) async throws }
protocol DiffFacet   { func presentDiff(_ versions: [(label: String, target: LocalTarget)]) }
protocol MergeFacet  { func presentMerge(_ versions: [(label: String, target: LocalTarget)],
                                         detail: ConflictSet?) async -> Data? }

// the widget aspect — rendered into a host's view tree, never out-of-process
protocol WidgetFacet { func render(_ host: PortalHost) -> View }

enum Scope {
    case global                    // across all projects: TODO's today view, search
    case project(ProjectContext)   // Home is just one of these (D38)
    case file(FileContext)         // project + path — what a nested widget gets
}
struct ProjectContext { let id: ProjectId; let name: String; let cloneURL: URL? }
```

**`Scope` has three cases, and `home` was already redundant** — D38 made Home structurally ordinary, a project containing a registry file. The `file` case is what a widget nested inside another widget receives; nothing forced it until nesting did.

**A widget declares its scopes in the manifest** rather than passively receiving one. Two requirements meet on that declaration: the widget's own contract, and the fact that Portal's configurable panel cannot offer sensible placements without knowing which widgets render where.

**A Portal-aware app edits files, not repositories** (D48). An app of our own may satisfy the application aspect — the notebook editor is the case — but it writes to the working tree like any editor and lets Portal's autosave commit. It depends on the kit, never on `portal-core`. Linking the core would put two processes on one repository, racing on quiescence detection and sync with only git's index lock between them. One tick loop per project, always Portal's.

// the widget aspect — rendered into a host's view tree, in-process (D49)
protocol PortalWidget {
    associatedtype Model: AnyObject & Observable
    associatedtype Body: View
    static var descriptor: WidgetDescriptor { get }                          // enumerable без instantiating
    static func makeModel(scope: Scope, context: PortalContext) throws -> Model
    @ViewBuilder static func makeBody(model: Model) -> Body
}
